def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    me = [h[0] for h in history]
    opp = [h[1] for h in history]

    # Consecutive opponent defections at the end
    opp_run_d = 0
    for a in reversed(opp):
        if a == 'D':
            opp_run_d += 1
        else:
            break

    # If opponent has defected 5 or more times in a row, punish
    if opp_run_d >= 5:
        return 'D'

    # If opponent just defected (1-4 times), decide whether to defect once
    if opp_run_d == 1:
        my_def_indices = [i for i, a in enumerate(me) if a == 'D']
        if my_def_indices:
            retaliations = 0
            total = 0
            for i in my_def_indices[-3:]:
                if i + 1 < n:
                    total += 1
                    if opp[i+1] == 'D':
                        retaliations += 1
            if total > 0 and retaliations / total < 0.5:
                return 'D'
        return 'C'

    if opp_run_d >= 2:
        return 'C'

    # Opponent cooperated last round.
    opp_d_total = opp.count('D')
    if opp_d_total == 0:
        if n % 4 == 0:
            return 'D'
        return 'C'

    # Adaptive exploitation based on retaliation rate
    my_def_indices = [i for i, a in enumerate(me) if a == 'D']
    if not my_def_indices:
        if n >= 8 and n % 8 == 0:
            return 'D'
        return 'C'

    retaliations = 0
    total = 0
    for i in my_def_indices[-5:]:
        if i + 1 < n:
            total += 1
            if opp[i+1] == 'D':
                retaliations += 1

    if total > 0:
        ret_rate = retaliations / total
        if ret_rate > 0.6:
            if n % 25 == 0 and opp_d_total < 3:
                return 'D'
            return 'C'
        elif ret_rate > 0.3:
            if n % 10 == 0:
                return 'D'
        else:
            if n % 5 == 0:
                return 'D'
    else:
        if n % 8 == 0:
            return 'D'

    return 'C'
